\label{theorem}
	\textit{For any given $\mu \in [0,\frac{1}{2}]$ it holds that}
	\begin{align*}
		\widetilde{\Sigma}_c^b &\cong (S^*S^3,\xi_{st}),\quad \textit{if } c < H(L_{1/2}), \\
		\widetilde{\Sigma}_c^b|_{\text{Fix}(\sigma)} &\cong (S^*S^2,\xi_{st}),\quad \textit{if } c < H(L_{1/2}).
	\end{align*}

Let $(\rho,\theta,\varphi) \in \partial B_r(0)$, i.e.,\ $\rho = r = 1 / \sqrt[3]{\lambda_2}$.\ Then, by Lemma \ref{lemma_1_U_min},
	\begin{align}\label{U>c}
		U(r,\theta,\varphi) \geq U(r,0,\frac{\pi}{2}) = - \frac{1}{r} - \frac{1}{2}r^2 \lambda_2 = - \frac{3}{2}\sqrt[3]{\lambda_2} = H(L_{1/2}) > c.
	\end{align}
	Therefore, $(r,\theta,\varphi)$ does not lie in $\mathscr{K}_c^b$, and hence, $\partial B_r(0) \cap \mathscr{K}_c^b = \emptyset$.\ Since $\mathscr{K}_c^b$ is connected and contains the origin in its closure, $\mathscr{K}_c^b$ is contained in $B_r(0)$.\

Let $(\rho,\theta,\varphi) \in B_r(0)$ with $\rho \in (0,r)$.\ Since $\lambda_2 > \lambda_1$ we have the following equivalences
	\begin{align}\label{equivalence}
		(\lambda_1 - \lambda_2)\sin^2 \theta \leq 0 \quad \Leftrightarrow \quad \lambda_2(\cos^2 \theta - 1) + \lambda_1 \sin^2 \theta \leq 0 \quad \Leftrightarrow \quad \lambda_2 \cos^2 \theta + \lambda_1 \sin^2 \theta \leq \lambda_2.
	\end{align}
	By using (\ref{equivalence}), we estimate
	\begin{align} \label{partial_U_rho}
		\frac{\partial U}{\partial \rho} = \frac{1}{\rho^2} - \rho \left( \lambda_2 \cos^2 \theta \sin^2 \varphi + \lambda_1 \sin^2 \theta \sin^2 \varphi - \cos^2 \varphi \right) \geq \frac{1}{\rho^2} - \lambda_2 \rho > 0.
	\end{align}
	The last strict inequality holds since the function $f \colon (0,r) \to \mathbb{R}$, $x \mapsto \frac{1}{x^2} - \lambda_2 x$ is strictly positive on its domain.\

We show that
\begin{align}\label{inequality_to_show_1}
	d H (X) | _{\Sigma_c^b} > 0.
\end{align}
The differential of the Hamiltonian (\ref{hamiltonian_1}) is given by
\begin{align}\label{dH}
	dH =  & p_x dp_x + p_y dp_y + p_z dp_z + p_x dy + y dp_x - p_y dx - x dp_y \\
	& + 2ax dx + 2by dy + z dz + \frac{x}{r^3} dx + \frac{y}{r^3} dy + \frac{z}{r^3} dz. \nonumber
\end{align}
By inserting the Liouville vector field (\ref{liouville_vector_field}) into (\ref{dH}) we obtain
\begin{align}\label{dHX}
	dH(X) = p_x y - p_y x + 2ax^2 + 2by^2 + z^2 + \frac{1}{r}.
\end{align}
Recall that $a = \frac{1}{2}(1-\lambda_2)$ and $b = \frac{1}{2}(1 - \lambda_1)$.\ In spherical coordinates the Liouville vector field (\ref{liouville_vector_field}) becomes
$$X = \rho \frac{\partial}{\partial \rho},$$
and (\ref{dHX}) reads
\begin{align}\label{dHX_2}
	dH(X) = & p_x \rho \sin \theta \sin \varphi - p_y \rho \cos \theta \sin \varphi + (1 + \lambda_2) \rho^2 \cos^2 \theta \sin^2 \varphi \\
	& + (1 - \lambda_1) \rho^2 \sin^2 \theta \sin^2 \varphi + \rho^2 \cos^2 \varphi + \frac{1}{\rho}. \nonumber
\end{align}
In view of $\frac{\partial U}{\partial \rho}$ from (\ref{partial_U_rho}), we write (\ref{dHX_2}) in the form
\begin{align*}
	dH(X) = \rho \sin \theta \sin \varphi (p_x + \rho \sin \theta \sin \varphi) - \rho \cos \theta \sin \varphi (p_y - \rho \cos \theta \sin \varphi) + \rho \frac{\partial U}{\partial \rho},
\end{align*}
which we estimate by using the Cauchy--Schwarz inequality,
\begin{align*}
	dH(X) &\geq \rho \frac{\partial U}{\partial \rho} - \rho \sin \varphi \sqrt{ (p_x + \rho \sin \theta \sin \varphi)^2 + (p_y - \rho \cos \theta \sin \varphi)^2 } \\
	& = \rho \frac{\partial U}{\partial \rho} - \rho \sin \varphi \sqrt{ 2 (H - U) - p_z^2 } \\
	& \geq \rho \frac{\partial U}{\partial \rho} - \rho \sin \varphi \sqrt{2 (H - U)}.
\end{align*}
Therefore, we have
$$ dH(X) | _{\Sigma_c^b} \geq \rho \left( \frac{\partial U}{\partial \rho} - \sin \varphi \sqrt{2(c-U)} \right). $$
Since the right hand side is independent of the momentum coordinates, to prove (\ref{inequality_to_show_1}) it is suffices to show that
\begin{align}\label{inequality_to_show_2}
	\left( \frac{\partial U}{\partial \rho} - \sin \varphi \sqrt{2(c-U)} \right) \bigg| _{\mathscr{K}_c^b} > 0.
\end{align}
Let $(\rho,\theta,\varphi) \in \mathscr{K}_c^b$.\ In particular, $ U(\rho,\theta,\varphi) \leq c$.\ By Corollary \ref{corollary}, we have $\rho < r$, and by (\ref{U>c}) it holds that $U(r,\theta,\varphi) > c$.\ Therefore, it exists $\tau \in [0,r-\rho)$ such that
$$ U(\rho + \tau, \theta, \varphi) = c. $$
By using Lemma \ref{lemma_2_U_pos} and Lemma \ref{lemma_3_U2} we obtain
\begin{align*}
	\left( \frac{\partial U}{\partial \rho} (\rho,\theta,\varphi) \right)^2 &= \left( \frac{\partial U}{\partial \rho} (\rho + \tau,\theta,\varphi) \right)^2 - \int_{0}^{\tau} \frac{d}{dt} \left( \frac{\partial U}{\partial \rho} (\rho + t,\theta,\varphi) \right)^2 dt \\
	&> -2 \int_{0}^{\tau} \frac{\partial U}{\partial \rho} (\rho + t,\theta,\varphi) \frac{\partial^2 U}{\partial \rho^2} (\rho + t,\theta,\varphi) dt \\
	&\geq 2 \sin^2 \varphi \int_{0}^{\tau} \frac{\partial U}{\partial \rho} (\rho + t,\theta,\varphi) dt \\
	&= 2 \sin^2 \varphi \left( U(\rho + \tau,\theta,\varphi) - U(\rho,\theta,\varphi) \right) \\
	&= 2 \sin^2 \varphi \left( c - U(\rho,\theta,\varphi) \right).
\end{align*}
Therefore, by using Lemma \ref{lemma_2_U_pos} once more, we imply
$$ \frac{\partial U}{\partial \rho} (\rho,\theta,\varphi) > \sin \varphi \sqrt{ 2 \left( c - U(\rho,\theta,\varphi) \right)}, $$
which shows (\ref{inequality_to_show_2}) and thereby the proposition.\

\label{prop}
	\textit{For $\varepsilon > 0 $ small enough, the natural Liouville vector field on $T^*S^3$ given by}
	\begin{align} \label{liouville_v_f}
		X = \sum_{i = 0}^{3} \eta_i \frac{\partial}{\partial \eta_i},
	\end{align}
	\textit{is transverse to $Q^{-1}(\frac{1}{2})$ over points $(\xi,\eta)$ satisfying (\ref{points_near_origin}).}

We show that for $\varepsilon > 0$ small enough it holds that
	\begin{align}\label{to_show}
		dQ(X) | _{Q^{-1}(\frac{1}{2})} > 0.
	\end{align}
	The computation of $dQ(X)$, in view of (\ref{Hamiltonian_Q}) and (\ref{liouville_v_f}), yields
	\begin{align*}
		dQ(X) &= |\eta|^2 f(\xi,\eta)^2 + |\eta|^2 f(\xi,\eta) \sum_{i=0}^{3} \frac{\partial f}{\partial \eta_i} (\xi,\eta) \eta_i \\
		&= 2 Q + |\eta|^2 f(\xi,\eta) (1-\xi_0) ( \eta_1 \xi_2 - \eta_2 \xi_1 + 2a g_1^2 + 2b g_2^2 + g_3^2 ).
	\end{align*}
	In order to prove (\ref{to_show}), we first show that we can choose $\varepsilon > 0$ so small such that
	\begin{align}\label{bound_lower_f}
		|f(\xi,\eta)| \geq \frac{1}{2}.
	\end{align}
	Since the energy value $c < H(L_{1/2}) = -\frac{3}{2}\sqrt[3]{\lambda_2}$ is negative, and in fact less then $-\frac{3}{2}$, the quantity $c + \frac{1}{2}$ is negative as well.\ Notice from Figure \ref{figure_2_quantities} that $a<0$, $|a|\leq 1$ and $b>0$.\ Therefore, $b g_2^2 + \frac{1}{2} g_3^2 - (c + \frac{1}{2})$ is positive.\ By using these, we estimate
	\begin{align*}
		|f(\xi,\eta)| &= \left| 1 + (\eta_1 \xi_2 - \eta_2 \xi_1)(1-\xi_0) + (a g_1^2 + b g_2^2 + \frac{1}{2} g_3^2)(1 - \xi_0) - (c + \frac{1}{2})(1 - \xi_0) \right| \\
		&= \left| 1 + ( b g_2^2 + \frac{1}{2} g_3^2 - (c + \frac{1}{2}) )(1-\xi_0) + (\eta_1 \xi_2 - \eta_2 \xi_1)(1-\xi_0) + a g_1^2(1 - \xi_0) \right| \\
		&\geq 1 - |\eta_1 \xi_2 - \eta_2 \xi_1|(1-\xi_0) - |a|g_1^2(1-\xi_0) \\
		&\geq 1 - |\eta_1 \xi_2 - \eta_2 \xi_1|(1-\xi_0) - g_1^2(1-\xi_0).
	\end{align*}
	Furthermore, $|\eta_1 \xi_2 - \eta_2 \xi_1| \leq |\eta||\xi|$, and because $|\xi|=1$, we have in view of (\ref{points_near_origin}),
	\begin{align}\label{inequality_epsilon}
		|\eta_1 \xi_2 - \eta_2 \xi_1|(1-\xi_0) \leq |\eta|(1-\xi_0) < \varepsilon.
	\end{align}
	This implies,
	$$ |f(\xi,\eta)| \geq 1 - \varepsilon - g_1^2(1-\xi_0). $$
	If $\varepsilon$ approaches 0, then $\xi_0 \to 1$, which means that we can choose $\varepsilon$ so small such that (\ref{bound_lower_f}) holds.\ By using the level set condition $Q^{-1}(\frac{1}{2})$ together with the lower bound (\ref{bound_lower_f}) for $|f(\xi,\eta)|$, we find
	$$ \frac{1}{2} = Q(\xi,\eta) = \frac{1}{2} |\eta|^2 f(\xi,\eta)^2 \geq \frac{1}{2} |\eta|^2 \frac{1}{2}, $$
	which gives an upper bound for $|\eta|$, i.e.,\
	\begin{align}\label{bound_eta}
		|\eta| \leq 2.
	\end{align}
	We may write
	$$ dQ(X) \geq 2 Q - |\eta|^2 \left| f(\xi,\eta) \right| \left| (1-\xi_0) \left( \eta_1 \xi_2 - \eta_2 \xi_1 + 2a g_1^2 + 2b g_2^2 + g_3^2 \right) \right|. $$
	Notice that by (\ref{bound_eta}) we obtain
	$$|\eta||\eta||f(\xi,\eta)| \leq 2 \sqrt{ 2Q(\xi,\eta) } = 2 \sqrt{2 \frac{1}{2}} = 2, $$
	which implies, together with (\ref{inequality_epsilon}),
	\begin{align*}
		dQ(X) &\geq 1 -2 \left( \left| (1-\xi_0) (\eta_1 \xi_2 - \eta_2 \xi_1) \right| + \left| (1-\xi_0) (2a g_1^2 + 2b g_2^2 + g_3^2 ) \right| \right) \\
		&\geq 1 -2 \varepsilon \left(1 + |2a g_1^2 + 2b g_2^2 + g_3^2| \right).
	\end{align*}
	Since the latter term can be bounded by some constant $A$ on a compact set away from the origin, we obtain
	$$dQ(X) \geq 1 - 2\varepsilon (1 + A). $$
	Now we choose $\varepsilon$ sufficiently small such that $dQ(X)>0$, which proves (\ref{to_show}).\
